/**
 * Animated film grain, generated by an SVG turbulence filter rather than a
 * tiled PNG.
 *
 * Multiplied rather than soft-lit: on a light ground, soft-light washes the
 * page out, while multiply reads as paper stock. `fractalNoise` is centred on
 * mid-grey, so at low opacity this adds texture without shifting the palette.
 */
export default function Grain() {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 z-[100] overflow-hidden mix-blend-multiply"
      style={{ opacity: 0.16 }}
    >
      <svg className="grain-layer absolute -inset-[100%] h-[300%] w-[300%]">
        <filter id="aqualume-grain">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.82"
            numOctaves="3"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#aqualume-grain)" />
      </svg>
    </div>
  );
}
